import { Integration } from "./base.ts";
import { config } from "../config.ts";
import { encode as base64Encode } from "https://deno.land/std@0.208.0/encoding/base64.ts";
import { marked } from "https://esm.sh/marked@11.1.1";

// HTML Email Template Generator
function generateHtmlEmail(contentItems: Array<{content: string, date: string, citations?: string[]}>, subject: string, outputTitle?: string): string {
  console.log('[Gmail Template] Generating HTML for', contentItems.length, 'items');
  
  if (contentItems.length === 0) {
    console.log('[Gmail Template] WARNING: No content items provided!');
  }
  
  const contentHtml = contentItems.map((item, index) => {
    console.log(`[Gmail Template] Processing item ${index + 1}:`, {
      dateLength: item.date.length,
      contentLength: item.content.length,
      contentPreview: item.content.substring(0, 50),
      citationsCount: item.citations?.length || 0
    });
    
    // Convert markdown to HTML
    const htmlContent = marked.parse(item.content);
    
    // Generate citations HTML if present
    let citationsHtml = '';
    if (item.citations && item.citations.length > 0) {
      const citationsList = item.citations.map((citation, idx) => {
        // Escape the citation URL for HTML
        const escapedUrl = citation
          .replace(/&/g, '&amp;')
          .replace(/</g, '&lt;')
          .replace(/>/g, '&gt;')
          .replace(/"/g, '&quot;');
        
        return `
        <li style="margin-bottom: 8px;">
          <a href="${escapedUrl}" style="color: #6b9bd1; text-decoration: none; word-break: break-all;" target="_blank">
            [${idx + 1}] ${escapedUrl}
          </a>
        </li>`;
      }).join('');
      
      citationsHtml = `
      <div style="margin-top: 24px; padding-top: 20px; border-top: 1px solid #3a3a3a;">
        <div style="font-family: 'Libre Franklin', -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif; font-size: 14px; color: #999; margin-bottom: 12px; font-weight: 600;">
          Sources:
        </div>
        <ul style="margin: 0; padding-left: 20px; font-family: 'Libre Franklin', -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif; font-size: 13px; color: #999; line-height: 1.6;">
          ${citationsList}
        </ul>
      </div>`;
    }
    
    return `
    <div style="background: #242424; border: 1px solid #3a3a3a; border-radius: 0; padding: 24px; margin-bottom: 24px;">
      <div style="font-family: 'Libre Franklin', -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif; font-size: 14px; color: #b0b0b0; margin-bottom: 16px; padding-bottom: 12px; border-bottom: 1px solid #3a3a3a;">
        ${item.date}
      </div>
      <div style="font-family: Georgia, 'Times New Roman', serif; font-size: 16px; line-height: 1.7; color: #d1d1d1; word-break: break-word;">
        ${htmlContent}
      </div>
      ${citationsHtml}
    </div>
  `}).join('');
  
  console.log('[Gmail Template] Generated HTML length:', contentHtml.length);

  return `
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${subject}</title>
</head>
<body style="margin: 0; padding: 0; font-family: Georgia, 'Times New Roman', serif; background-color: #1a1a1a;">
  <table width="100%" cellpadding="0" cellspacing="0" style="background-color: #1a1a1a;">
    <tr>
      <td align="center" style="padding: 40px 20px;">
        <table width="100%" cellpadding="0" cellspacing="0" style="max-width: 700px; background-color: #1a1a1a; border: 1px solid #2a2a2a;">
          <!-- Header -->
          <tr>
            <td style="background-color: #1a1a1a; border-bottom: 1px solid #2a2a2a; padding: 32px 40px 24px 40px; text-align: center;">
              <img src="data:image/png;base64," alt="Palimpsest" style="height: 100px; width: auto; display: block; margin: 0 auto 12px auto;" />
              ${outputTitle ? `
                <p style="font-family: 'Libre Franklin', -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif; font-size: 16px; color: #999; margin: 0; font-weight: 400;">
                  Topic - ${outputTitle.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#039;')}
                </p>
              ` : ''}
            </td>
          </tr>
          
          <!-- Content -->
          <tr>
            <td style="padding: 40px; background-color: #1a1a1a;">
              ${contentHtml}
            </td>
          </tr>
          
          <!-- Footer -->
          <tr>
            <td style="background-color: #242424; border-top: 1px solid #2a2a2a; padding: 24px 40px; text-align: center;">
              <p style="font-family: 'Libre Franklin', -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif; font-size: 14px; color: #808080; margin: 0;">
                Generated by Palimpsest
              </p>
            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>
</body>
</html>
  `.trim();
}

export class GmailIntegration extends Integration {
  name = "gmail";
  requiredEnvVars = ["GMAIL_CLIENT_ID", "GMAIL_CLIENT_SECRET", "GMAIL_REFRESH_TOKEN", "GMAIL_USER_EMAIL"];

  async validate(): Promise<boolean> {
    console.log("[Gmail] Validating integration...");
    const envCheck = this.checkEnvVars();
    if (!envCheck.valid) {
      console.log("[Gmail] ❌ Environment variables not set");
      return false;
    }

    // Actually test the credentials by attempting to get an access token
    try {
      console.log("[Gmail] Testing OAuth credentials...");
      const tokenResponse = await fetch("https://oauth2.googleapis.com/token", {
        method: "POST",
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
        },
        body: new URLSearchParams({
          client_id: config.gmail.clientId,
          client_secret: config.gmail.clientSecret,
          refresh_token: config.gmail.refreshToken,
          grant_type: "refresh_token",
        }),
      });

      if (tokenResponse.ok) {
        console.log("[Gmail] ✅ Connected successfully");
      } else {
        const errorText = await tokenResponse.text();
        console.log(`[Gmail] ❌ OAuth error: ${tokenResponse.status} - ${errorText}`);
      }
      return tokenResponse.ok;
    } catch (error) {
      console.error("[Gmail] ❌ Validation error:", error);
      return false;
    }
  }

  // Get access token from refresh token
  private async getAccessToken(): Promise<string> {
    console.log('[Gmail] Requesting access token...');
    
    const tokenResponse = await fetch("https://oauth2.googleapis.com/token", {
      method: "POST",
      headers: {
        "Content-Type": "application/x-www-form-urlencoded",
      },
      body: new URLSearchParams({
        client_id: config.gmail.clientId,
        client_secret: config.gmail.clientSecret,
        refresh_token: config.gmail.refreshToken,
        grant_type: "refresh_token",
      }),
    });

    if (!tokenResponse.ok) {
      const errorText = await tokenResponse.text();
      console.error(`[Gmail] ❌ Failed to get access token: ${tokenResponse.status}`, errorText);
      throw new Error(`Failed to get Gmail access token: ${tokenResponse.status} - ${errorText}`);
    }

    const tokenData = await tokenResponse.json();
    console.log('[Gmail] ✅ Access token retrieved successfully');
    return tokenData.access_token;
  }

  // Create a draft email
  async execute(outputConfig: any): Promise<any> {
    console.log('[Gmail] 📧 Starting draft creation...');
    console.log('[Gmail] Config:', {
      to: outputConfig.to,
      subject: outputConfig.subject,
      bodyLength: outputConfig.body?.length || 0,
      contentType: outputConfig.contentType || 'text/plain',
      labels: outputConfig.labels || []
    });

    const { 
      to, 
      subject, 
      body, 
      contentType = "text/plain",
      labels = []
    } = outputConfig;

    if (!to || !subject || !body) {
      console.error('[Gmail] ❌ Missing required fields');
      throw new Error("Gmail integration requires 'to', 'subject', and 'body' in config");
    }

    const accessToken = await this.getAccessToken();

    // Construct MIME message
    console.log('[Gmail] Constructing MIME message...');
    const messageParts = [
      `To: ${to}`,
      `From: ${config.gmail.userEmail}`,
      `Subject: ${subject}`,
      `Content-Type: ${contentType}; charset=utf-8`,
      "",
      body,
    ];

    const message = messageParts.join("\r\n");
    console.log('[Gmail] Message size:', message.length, 'characters');
    
    // Encode message in base64url format using Deno's UTF-8 safe encoder
    console.log('[Gmail] Starting base64 encoding with Deno encoder...');
    const encoder = new TextEncoder();
    const messageBytes = encoder.encode(message);
    console.log('[Gmail] Encoded to bytes, length:', messageBytes.length);
    
    const base64 = base64Encode(messageBytes);
    console.log('[Gmail] Base64 encoded, length:', base64.length);
    
    const encodedMessage = base64
      .replace(/\+/g, "-")
      .replace(/\//g, "_")
      .replace(/=+$/, "");
    
    console.log('[Gmail] ✅ Message encoded successfully, length:', encodedMessage.length);

    // Prepare draft payload
    const draftPayload: any = {
      message: {
        raw: encodedMessage,
      },
    };

    // Add labels if provided (need to get label IDs first)
    if (labels && labels.length > 0) {
      console.log('[Gmail] Processing labels:', labels);
      const labelIds = await this.getLabelIds(accessToken, labels);
      console.log('[Gmail] Label IDs obtained:', labelIds);
      if (labelIds.length > 0) {
        draftPayload.message.labelIds = labelIds;
      }
    }

    // Create draft via Gmail API
    console.log('[Gmail] Calling Gmail API to create draft...');
    console.log('[Gmail] API endpoint: https://gmail.googleapis.com/gmail/v1/users/me/drafts');
    
    const response = await fetch("https://gmail.googleapis.com/gmail/v1/users/me/drafts", {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${accessToken}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify(draftPayload),
    });

    console.log('[Gmail] API response status:', response.status, response.statusText);

    if (!response.ok) {
      const errorText = await response.text();
      console.error('[Gmail] ❌ API error response:', errorText);
      throw new Error(`Gmail API error: ${response.status} - ${errorText}`);
    }

    const data = await response.json();
    console.log('[Gmail] ✅ Draft created successfully!');
    console.log('[Gmail] Draft ID:', data.id);
    console.log('[Gmail] Message ID:', data.message?.id);
    
    return {
      draftId: data.id,
      messageId: data.message?.id,
      timestamp: new Date().toISOString(),
    };
  }

  // Get or create label IDs from label names
  private async getLabelIds(accessToken: string, labelNames: string[]): Promise<string[]> {
    console.log('[Gmail] Getting/creating label IDs for:', labelNames);
    
    try {
      // Get all existing labels
      console.log('[Gmail] Fetching existing labels...');
      const response = await fetch("https://gmail.googleapis.com/gmail/v1/users/me/labels", {
        headers: {
          "Authorization": `Bearer ${accessToken}`,
        },
      });

      if (!response.ok) {
        console.error("[Gmail] ❌ Failed to fetch Gmail labels:", response.status);
        return [];
      }

      const data = await response.json();
      const existingLabels = data.labels || [];
      console.log('[Gmail] Found', existingLabels.length, 'existing labels');
      
      const labelIds: string[] = [];

      for (const labelName of labelNames) {
        // Check if label exists
        const existingLabel = existingLabels.find((l: any) => 
          l.name.toLowerCase() === labelName.toLowerCase()
        );

        if (existingLabel) {
          console.log(`[Gmail] ✅ Label "${labelName}" exists, ID:`, existingLabel.id);
          labelIds.push(existingLabel.id);
        } else {
          // Create new label
          console.log(`[Gmail] Creating new label "${labelName}"...`);
          const createResponse = await fetch("https://gmail.googleapis.com/gmail/v1/users/me/labels", {
            method: "POST",
            headers: {
              "Authorization": `Bearer ${accessToken}`,
              "Content-Type": "application/json",
            },
            body: JSON.stringify({
              name: labelName,
              labelListVisibility: "labelShow",
              messageListVisibility: "show",
            }),
          });

          if (createResponse.ok) {
            const newLabel = await createResponse.json();
            console.log(`[Gmail] ✅ Created label "${labelName}", ID:`, newLabel.id);
            labelIds.push(newLabel.id);
          } else {
            console.error(`[Gmail] ❌ Failed to create label "${labelName}":`, createResponse.status);
          }
        }
      }

      console.log('[Gmail] Final label IDs:', labelIds);
      return labelIds;
    } catch (error) {
      console.error("[Gmail] ❌ Error getting/creating labels:", error);
      return [];
    }
  }

  // Send styled HTML email with content items
  async sendStyledEmail(config: {
    to: string;
    subject: string;
    contentItems: Array<{content: string, date: string}>;
    labels?: string[];
    outputTitle?: string;
  }): Promise<any> {
    console.log('[Gmail] 📧 Sending styled HTML email...');
    
    const htmlBody = generateHtmlEmail(config.contentItems, config.subject, config.outputTitle);
    
    return await this.sendEmail({
      to: config.to,
      subject: config.subject,
      body: htmlBody,
      contentType: "text/html",
      labels: config.labels || [],
    });
  }

  // Send email directly (not as draft) with labels support
  async sendEmail(outputConfig: any): Promise<any> {
    console.log('[Gmail] 📧 Starting email send...');
    console.log('[Gmail] Config:', {
      to: outputConfig.to,
      subject: outputConfig.subject,
      bodyLength: outputConfig.body?.length || 0,
      contentType: outputConfig.contentType || 'text/plain',
      labels: outputConfig.labels || []
    });

    const { 
      to, 
      subject, 
      body, 
      contentType = "text/plain",
      labels = []
    } = outputConfig;

    if (!to || !subject || !body) {
      console.error('[Gmail] ❌ Missing required fields');
      throw new Error("Gmail integration requires 'to', 'subject', and 'body' in config");
    }

    const accessToken = await this.getAccessToken();

    // Always add "Palimpsest App" label first
    const allLabels = ['Palimpsest App', ...labels];
    console.log('[Gmail] Labels to apply:', allLabels);

    // Construct MIME message
    console.log('[Gmail] Constructing MIME message...');
    
    let message: string;
    
    if (contentType === "text/html") {
      // For HTML emails, create multipart/alternative with both plain text and HTML
      const boundary = "palimpsest_boundary_" + Date.now();
      
      // Generate plain text version by stripping HTML tags
      const plainText = body
        .replace(/<style[^>]*>.*?<\/style>/gs, '')
        .replace(/<script[^>]*>.*?<\/script>/gs, '')
        .replace(/<[^>]+>/g, '')
        .replace(/&nbsp;/g, ' ')
        .replace(/&lt;/g, '<')
        .replace(/&gt;/g, '>')
        .replace(/&amp;/g, '&')
        .replace(/&quot;/g, '"')
        .replace(/&#039;/g, "'")
        .replace(/<br>/g, '\n')
        .trim();
      
      const messageParts = [
        `To: ${to}`,
        `From: ${config.gmail.userEmail}`,
        `Subject: ${subject}`,
        `MIME-Version: 1.0`,
        `Content-Type: multipart/alternative; boundary="${boundary}"`,
        "",
        `--${boundary}`,
        `Content-Type: text/plain; charset=UTF-8`,
        "",
        plainText,
        "",
        `--${boundary}`,
        `Content-Type: text/html; charset=UTF-8`,
        "",
        body,
        "",
        `--${boundary}--`
      ];
      
      message = messageParts.join("\r\n");
      console.log('[Gmail] Created multipart/alternative message');
    } else {
      // Plain text email
      const messageParts = [
        `To: ${to}`,
        `From: ${config.gmail.userEmail}`,
        `Subject: ${subject}`,
        `Content-Type: ${contentType}; charset=utf-8`,
        "",
        body,
      ];
      
      message = messageParts.join("\r\n");
    }
    
    console.log('[Gmail] Message size:', message.length, 'characters');
    
    // Encode message in base64url format using Deno's UTF-8 safe encoder
    console.log('[Gmail] Starting base64 encoding with Deno encoder...');
    const encoder = new TextEncoder();
    const messageBytes = encoder.encode(message);
    console.log('[Gmail] Encoded to bytes, length:', messageBytes.length);
    
    const base64 = base64Encode(messageBytes);
    console.log('[Gmail] Base64 encoded, length:', base64.length);
    
    const encodedMessage = base64
      .replace(/\+/g, "-")
      .replace(/\//g, "_")
      .replace(/=+$/, "");
    
    console.log('[Gmail] ✅ Message encoded successfully, length:', encodedMessage.length);

    // Send email via Gmail API
    console.log('[Gmail] Sending email...');
    const response = await fetch("https://gmail.googleapis.com/gmail/v1/users/me/messages/send", {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${accessToken}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        raw: encodedMessage,
      }),
    });

    console.log('[Gmail] Send response status:', response.status, response.statusText);

    if (!response.ok) {
      const errorText = await response.text();
      console.error('[Gmail] ❌ Send error:', errorText);
      throw new Error(`Gmail API error: ${response.status} - ${errorText}`);
    }

    const data = await response.json();
    const messageId = data.id;
    console.log('[Gmail] ✅ Email sent successfully! Message ID:', messageId);

    // Apply labels to the sent message
    if (allLabels.length > 0) {
      console.log('[Gmail] Applying labels to sent message...');
      const labelIds = await this.getLabelIds(accessToken, allLabels);
      
      if (labelIds.length > 0) {
        const modifyResponse = await fetch(
          `https://gmail.googleapis.com/gmail/v1/users/me/messages/${messageId}/modify`,
          {
            method: "POST",
            headers: {
              "Authorization": `Bearer ${accessToken}`,
              "Content-Type": "application/json",
            },
            body: JSON.stringify({
              addLabelIds: labelIds,
            }),
          }
        );

        if (modifyResponse.ok) {
          console.log('[Gmail] ✅ Labels applied successfully:', allLabels);
        } else {
          const errorText = await modifyResponse.text();
          console.error('[Gmail] ⚠️  Failed to apply labels:', errorText);
        }
      }
    }
    
    return {
      messageId: data.id,
      threadId: data.threadId,
      timestamp: new Date().toISOString(),
      labelsApplied: allLabels,
    };
  }

  getConfigSchema(): object {
    return {
      type: "object",
      properties: {
        to: {
          type: "string",
          description: "Recipient email address (or comma-separated for multiple)",
          required: true,
        },
        subject: {
          type: "string",
          description: "Email subject line",
          required: true,
        },
        body: {
          type: "string",
          description: "Email body content",
          required: true,
        },
        contentType: {
          type: "string",
          description: "Content type (text/plain or text/html)",
          default: "text/plain",
          enum: ["text/plain", "text/html"],
        },
        labels: {
          type: "array",
          description: "Gmail labels to apply to the message",
          items: {
            type: "string",
          },
          default: [],
        },
      },
    };
  }
}

export const gmailIntegration = new GmailIntegration();
